source='''from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find background zeros connected to the grid edge.
    exterior = set()
    queue = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                queue.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                queue.append((nr, nc))

    enclosed = {
        (r, c) for r in range(h) for c in range(w)
        if grid[r][c] == 0 and (r, c) not in exterior
    }

    # Color the one-cell inner rim of enclosed regions, including diagonal adjacency.
    inner = set()
    boundary = set()
    for r, c in enclosed:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (dr or dc) and 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    inner.add((r, c))
                    boundary.add((nr, nc))

    # Extend the surrounding color around each 4-connected 1-component bounding a cavity.
    component = set(boundary)
    queue = deque(boundary)
    while queue:
        r, c = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                    and (nr, nc) not in component):
                component.add((nr, nc))
                queue.append((nr, nc))

    for r, c in inner:
        out[r][c] = 3
    for r, c in component:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr, nc = r + dr, c + dc
                if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                        and (nr, nc) not in enclosed):
                    out[nr][nc] = 2
    return out
